import { Marked, Renderer } from './marked.js';

const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

export function slugify(text, seen) {
  let s = String(text).toLowerCase().replace(/[^\p{L}\p{N} _-]/gu, '').replace(/ /g, '-');
  if (seen) {
    if (seen.has(s)) { const n = seen.get(s); seen.set(s, n + 1); const r = `${s}-${n}`; seen.set(r, seen.get(r) ?? 1); return r; }
    seen.set(s, 1);
  }
  return s;
}

function safeUrl(href) {
  if (href == null) return href;
  const probe = String(href).replace(/[\u0000- \u007f-\u009f]/g, '').toLowerCase();
  const m = /^([a-z][a-z0-9+.-]*):/.exec(probe);
  if (m) {
    if (['javascript', 'vbscript', 'file'].includes(m[1])) return '#';
    if (m[1] === 'data' && !/^data:image\/(png|gif|jpeg|webp);/.test(probe)) return '#';
  }
  return href;
}

function plain(tokens) {
  let out = '';
  for (const t of tokens || []) {
    if (t.type === 'br') out += '\n';
    else if (t.type === 'codespan') out += t.text.replace(/&(amp|lt|gt|quot|#39);/g, (m, c) => ({ amp: '&', lt: '<', gt: '>', quot: '"', '#39': "'" })[c]);
    else if (t.tokens) out += plain(t.tokens);
    else if (t.type === 'html') out += t.text;
    else out += t.text ?? t.raw ?? '';
  }
  return out.replace(/&(amp|lt|gt|quot|#39);/g, (m, c) => ({ amp: '&', lt: '<', gt: '>', quot: '"', '#39': "'" })[c]);
}

function make(headingIds) {
  const seen = new Map();
  const marked = new Marked({ gfm: true, breaks: false });
  marked.use({
    renderer: {
      html(tok) { return esc(tok.text ?? tok.raw ?? ''); },
      link(tok) {
        const href = safeUrl(tok.href);
        const t = tok.title ? ` title="${esc(tok.title)}"` : '';
        return `<a href="${esc(encodeHref(href))}"${t}>${this.parser.parseInline(tok.tokens)}</a>`;
      },
      image(tok) {
        const href = safeUrl(tok.href);
        const t = tok.title ? ` title="${esc(tok.title)}"` : '';
        return `<img src="${esc(encodeHref(href))}" alt="${esc(plain(tok.tokens))}"${t} />`;
      },
      heading(tok) {
        const inner = this.parser.parseInline(tok.tokens);
        const id = headingIds ? ` id="${esc(slugify(plain(tok.tokens), seen))}"` : '';
        return `<h${tok.depth}${id}>${inner}</h${tok.depth}>\n`;
      },
      code(tok) {
        const lang = ((tok.lang || '').match(/^\S+/) || [''])[0];
        const cls = lang ? ` class="language-${esc(lang)}"` : '';
        const body = esc(tok.text.replace(/\n$/, '')) + '\n';
        return `<pre><code${cls}>${tok.text === '' ? '' : body}</code></pre>\n`;
      },
    },
  });
  return marked;
}

function encodeHref(h) {
  try { return encodeURI(decodeURI(h)); } catch { return h; }
}

export function render(markdown, { headingIds = false } = {}) {
  const html = make(headingIds).parse(String(markdown ?? '').replace(/\r\n?/g, '\n'), { async: false });
  return html.replace(/&#39;/g, "'");
}

export function toc(markdown) {
  const seen = new Map();
  const out = [];
  const m = new Marked({ gfm: true });
  const walk = tokens => {
    for (const t of tokens) {
      if (t.type === 'heading') out.push({ level: t.depth, text: plain(t.tokens), slug: slugify(plain(t.tokens), seen) });
      else {
        if (t.tokens && t.type !== 'paragraph') walk(t.tokens);
        if (t.items) walk(t.items);
      }
    }
  };
  walk(m.lexer(String(markdown ?? '').replace(/\r\n?/g, '\n')));
  return out;
}
